package cn.binbin.crm;
import jakarta.validation.Valid;import jakarta.validation.constraints.*;import java.time.*;import java.util.*;import org.springframework.stereotype.Service;import static cn.binbin.crm.TradeService.*;
@Service
public class PerformanceService {
 public record TargetInput(UUID memberId,UUID departmentId,@NotNull LocalDate periodStart,@Min(1) @Max(12) int periodMonths,@Min(1) @Max(100000000000L) long targetCents,@Min(0) long expectedVersion){}
 public record RuleInput(@NotBlank @Size(max=100) String name,@NotEmpty @Size(max=20) List<CommissionAmounts.Tier> tiers,boolean active,@Min(0) long expectedVersion){}
 public record Calculate(@NotNull UUID memberId,@NotNull UUID ruleId,@NotNull LocalDate periodStart,@Min(0) long expectedVersion){}
 public record Decision(@Min(0) long expectedVersion,@Size(max=500) String reason,@Min(-100000000000L) @Max(100000000000L) Long deltaCents){}
 public record WeeklyInput(@NotNull LocalDate weekStart,@NotBlank @Size(max=4000) String progress,@Size(max=4000) String achievements,@Size(max=4000) String risks,@NotBlank @Size(max=4000) String nextActions,@Min(0) long expectedVersion){}
 private final TradeService t;
 public PerformanceService(TradeService t){this.t=t;}
 private boolean manager(AuthService.Actor a){return a.tenant().roles().contains("SALES_MANAGER")&&a.tradeAccess().contracts().write();}
 private void managerial(AuthService.Actor a){if(!manager(a))throw ApiError.forbidden("需要销售主管写入权限");}
 private void member(AuthService.Actor a,UUID id,boolean write){if(id==null)throw ApiError.bad("请选择成员");var p=t.params(a);p.put("id",id);var scope=a.tradeAccess().contracts();p.put("all",write?scope.writeAll():scope.readAll());p.put("dept",write?scope.writeDepartment():scope.readDepartment());t.one("SELECT id FROM sys_tenant_member WHERE tenant_id=:tenant AND id=:id AND(:all OR id=:member OR(:dept AND department_id=:department))",p);}
 private void department(AuthService.Actor a,UUID id,boolean write){var p=t.params(a);p.put("id",id);var scope=a.tradeAccess().contracts();p.put("all",write?scope.writeAll():scope.readAll());p.put("dept",write?scope.writeDepartment():scope.readDepartment());t.one("SELECT id FROM org_department WHERE tenant_id=:tenant AND id=:id AND(:all OR(:dept AND id=:department))",p);}
 private void version(Map<String,Object> r,long expected){if(number(r,"version")!=expected)throw ApiError.conflict("记录已变化，请刷新");}
 private void month(LocalDate d){date(d);if(d.getDayOfMonth()!=1)throw ApiError.bad("月份需填写每月1日");}
 private void separate(AuthService.Actor a,UUID member){UUID user=t.db.queryForObject("SELECT user_id FROM sys_tenant_member WHERE tenant_id=:tenant AND id=:id",map("tenant",a.tenant().id(),"id",member),UUID.class);if(a.session().userId().equals(user))throw ApiError.forbidden("需由另一位主管复核，不能审核本人记录");}
 public Object options(AuthService.Session s){return t.scoped(s,"contract",false,a->{var p=t.params(a);var scope=a.tradeAccess().contracts();p.put("all",scope.readAll());p.put("dept",scope.readDepartment());return map("members",t.rows("SELECT id,display_name AS name,department_id FROM sys_tenant_member WHERE tenant_id=:tenant AND status='ACTIVE' AND(:all OR id=:member OR(:dept AND department_id=:department)) ORDER BY display_name",p),"departments",t.rows("SELECT id,name FROM org_department WHERE tenant_id=:tenant AND(:all OR(:dept AND id=:department)) ORDER BY name",p),"manager",manager(a));});}
 private List<Map<String,Object>> sources(AuthService.Actor a,UUID member,UUID department,LocalDate start,LocalDate end){var p=t.params(a);p.putAll(map("owner",member,"dept",department,"from",start,"to",end));String w=READ+" AND(cast(:owner AS uuid) IS NULL OR k.owner_member_id=:owner) AND(cast(:dept AS uuid) IS NULL OR m.department_id=:dept)";return t.rows("SELECT r.id AS source_id,'RECEIPT' AS kind,r.received_date AS business_date,r.amount_cents AS delta_cents"+FROM+" JOIN crm_receipt r ON r.tenant_id=k.tenant_id AND r.contract_id=k.id WHERE "+w+" AND r.status IN('CONFIRMED','REVERSED') AND r.received_date>=:from AND r.received_date<:to UNION ALL SELECT v.id AS source_id,'REVERSAL' AS kind,v.reversal_date AS business_date,-v.amount_cents AS delta_cents"+FROM+" JOIN crm_receipt_reversal v ON v.tenant_id=k.tenant_id AND v.contract_id=k.id WHERE "+w+" AND v.reversal_date>=:from AND v.reversal_date<:to ORDER BY kind,source_id",p);}
 private long actual(AuthService.Actor a,UUID member,UUID department,LocalDate start,LocalDate end){return sources(a,member,department,start,end).stream().mapToLong(r->number(r,"deltaCents")).reduce(0,Math::addExact);}
 private void targetScope(AuthService.Actor a,Map<String,Object> r,boolean write){if(r.get("memberId")!=null)member(a,(UUID)r.get("memberId"),write);else department(a,(UUID)r.get("departmentId"),write);}
 public Object targets(AuthService.Session s,int year){if(year<2000||year>2100)throw ApiError.bad("年份无效");return t.scoped(s,"contract",false,a->{var rows=t.rows("SELECT g.*,m.display_name AS member_name,d.name AS department_name FROM crm_sales_target g LEFT JOIN sys_tenant_member m ON m.tenant_id=g.tenant_id AND m.id=g.member_id LEFT JOIN org_department d ON d.tenant_id=g.tenant_id AND d.id=g.department_id WHERE g.tenant_id=:tenant AND extract(year FROM g.period_start)=:year ORDER BY g.period_start,g.period_months DESC",map("tenant",a.tenant().id(),"year",year));var result=new ArrayList<Map<String,Object>>();for(var r:rows){try{targetScope(a,r,false);var start=(LocalDate)r.get("periodStart");long net=actual(a,(UUID)r.get("memberId"),(UUID)r.get("departmentId"),start,start.plusMonths(number(r,"periodMonths")));r.put("actualCents",net);result.add(r);}catch(ApiError ignored){}}return map("items",result);});}
 public Object saveTarget(AuthService.Session s,UUID id,TargetInput i,String key,UUID trace){month(i.periodStart());if(!Set.of(1,12).contains(i.periodMonths())||i.periodMonths()==12&&i.periodStart().getMonthValue()!=1||(i.memberId()==null)==(i.departmentId()==null))throw ApiError.bad("目标需指定成员或部门，以及有效的年度/月度周期");return t.scoped(s,"contract",true,a->{managerial(a);targetScope(a,map("memberId",i.memberId(),"departmentId",i.departmentId()),true);var p=map("tenant",a.tenant().id(),"member",i.memberId(),"department",i.departmentId(),"start",i.periodStart(),"months",i.periodMonths(),"amount",i.targetCents());String match="tenant_id=:tenant AND member_id IS NOT DISTINCT FROM cast(:member AS uuid) AND department_id IS NOT DISTINCT FROM cast(:department AS uuid)";if(i.periodMonths()==1){long annual=t.db.queryForObject("SELECT coalesce(max(target_cents),0) FROM crm_sales_target WHERE "+match+" AND period_months=12 AND extract(year FROM period_start)=extract(year FROM cast(:start AS date))",p,Long.class);long other=t.db.queryForObject("SELECT coalesce(sum(target_cents),0)::bigint FROM crm_sales_target WHERE "+match+" AND period_months=1 AND extract(year FROM period_start)=extract(year FROM cast(:start AS date)) AND period_start<>:start",p,Long.class);if(annual>0&&other+i.targetCents()>annual)throw ApiError.conflict("月度目标合计不能超过年度目标");}else{long allocated=t.db.queryForObject("SELECT coalesce(sum(target_cents),0)::bigint FROM crm_sales_target WHERE "+match+" AND period_months=1 AND extract(year FROM period_start)=extract(year FROM cast(:start AS date))",p,Long.class);if(allocated>i.targetCents())throw ApiError.conflict("年度目标不能低于已拆分月度目标");}UUID selected=id==null?t.once(a,"target.create",key,i,()->{UUID n=UUID.randomUUID();p.put("id",n);t.db.update("INSERT INTO crm_sales_target(id,tenant_id,member_id,department_id,period_start,period_months,target_cents) VALUES(:id,:tenant,:member,:department,:start,:months,:amount)",p);event(a,"TARGET",n,0,"CREATED","",i,trace);return n;}):id;if(id!=null){var old=t.one("SELECT * FROM crm_sales_target WHERE tenant_id=:tenant AND id=:id",map("tenant",a.tenant().id(),"id",id));version(old,i.expectedVersion());if(!Objects.equals(old.get("memberId"),i.memberId())||!Objects.equals(old.get("departmentId"),i.departmentId())||!old.get("periodStart").equals(i.periodStart())||number(old,"periodMonths")!=i.periodMonths())throw ApiError.bad("已有目标不能更换对象或周期");p.put("id",id);t.db.update("UPDATE crm_sales_target SET target_cents=:amount,version=version+1,updated_at=now() WHERE tenant_id=:tenant AND id=:id",p);event(a,"TARGET",id,i.expectedVersion()+1,"UPDATED","",i,trace);}return t.one("SELECT * FROM crm_sales_target WHERE tenant_id=:tenant AND id=:id",map("tenant",a.tenant().id(),"id",selected));});}
 private List<CommissionAmounts.Tier> tiers(Object raw){try{return t.json.readValue(String.valueOf(raw),new com.fasterxml.jackson.core.type.TypeReference<List<CommissionAmounts.Tier>>(){});}catch(Exception e){throw new IllegalStateException("提成规则快照无效",e);}}
 public Object rules(AuthService.Session s){return t.scoped(s,"contract",false,a->map("items",t.rows("SELECT id,name,tiers::text AS tiers,active,version FROM crm_commission_rule WHERE tenant_id=:tenant ORDER BY created_at DESC",map("tenant",a.tenant().id())).stream().map(r->{r.put("tiers",tiers(r.get("tiers")));return r;}).toList()));}
 public Object rule(AuthService.Session s,UUID id,RuleInput i,String key,UUID trace){CommissionAmounts.validate(i.tiers());return t.scoped(s,"contract",true,a->{managerial(a);if(!a.tradeAccess().contracts().writeAll())throw ApiError.forbidden("企业提成规则需要全企业管理范围");UUID selected=id==null?t.once(a,"commission.rule.create",key,i,()->{UUID n=UUID.randomUUID();t.db.update("INSERT INTO crm_commission_rule(id,tenant_id,name,tiers,active) VALUES(:id,:tenant,:name,cast(:tiers AS jsonb),:active)",map("id",n,"tenant",a.tenant().id(),"name",text(i.name()),"tiers",t.body(i.tiers()),"active",i.active()));event(a,"RULE",n,0,"CREATED","",i,trace);return n;}):id;if(id!=null){var p=map("tenant",a.tenant().id(),"id",id,"version",i.expectedVersion(),"name",text(i.name()),"tiers",t.body(i.tiers()),"active",i.active());if(t.db.update("UPDATE crm_commission_rule SET name=:name,tiers=cast(:tiers AS jsonb),active=:active,version=version+1 WHERE tenant_id=:tenant AND id=:id AND version=:version",p)!=1)throw ApiError.conflict("规则已变化");event(a,"RULE",id,i.expectedVersion()+1,"UPDATED","",i,trace);}return t.one("SELECT id,name,version,active FROM crm_commission_rule WHERE tenant_id=:tenant AND id=:id",map("tenant",a.tenant().id(),"id",selected));});}
 private Map<String,Object> run(AuthService.Actor a,UUID id){var r=t.one("SELECT c.*,m.display_name AS member_name,(SELECT coalesce(sum(delta_cents),0)::bigint FROM crm_commission_adjustment z WHERE z.tenant_id=c.tenant_id AND z.run_id=c.id) AS adjustment_cents FROM crm_commission_run c JOIN sys_tenant_member m ON m.tenant_id=c.tenant_id AND m.id=c.member_id WHERE c.tenant_id=:tenant AND c.id=:id",map("tenant",a.tenant().id(),"id",id));member(a,(UUID)r.get("memberId"),false);r.put("ruleSnapshot",tiers(r.get("ruleSnapshot")));r.put("adjustments",t.rows("SELECT z.delta_cents,z.reason,z.created_at,m.display_name AS actor_name FROM crm_commission_adjustment z JOIN sys_tenant_member m ON m.tenant_id=z.tenant_id AND m.id=z.actor_member_id WHERE z.tenant_id=:tenant AND z.run_id=:id ORDER BY z.created_at",map("tenant",a.tenant().id(),"id",id)));return r;}
 public Object runs(AuthService.Session s,LocalDate period){month(period);return t.scoped(s,"contract",false,a->{var ids=t.db.queryForList("SELECT id FROM crm_commission_run WHERE tenant_id=:tenant AND period_start=:period ORDER BY created_at DESC",map("tenant",a.tenant().id(),"period",period),UUID.class);var result=new ArrayList<Map<String,Object>>();for(UUID id:ids)try{result.add(run(a,id));}catch(ApiError ignored){}return map("items",result);});}
 public Object calculate(AuthService.Session s,Calculate i,String key,UUID trace){month(i.periodStart());if(i.periodStart().isAfter(today()))throw ApiError.bad("不能试算未来月份");return t.scoped(s,"contract",true,a->{managerial(a);member(a,i.memberId(),true);UUID result=t.once(a,"commission.calculate",key,i,()->{var rule=t.one("SELECT *,tiers::text AS rule_tiers FROM crm_commission_rule WHERE tenant_id=:tenant AND id=:id AND active",map("tenant",a.tenant().id(),"id",i.ruleId()));var tiers=tiers(rule.get("ruleTiers"));var sources=sources(a,i.memberId(),null,i.periodStart(),i.periodStart().plusMonths(1));long base=sources.stream().mapToLong(r->number(r,"deltaCents")).sum();long commission=CommissionAmounts.calculate(base,tiers);String hash=Crypto.hash(t.body(sources));var existing=t.rows("SELECT * FROM crm_commission_run WHERE tenant_id=:tenant AND member_id=:member AND period_start=:period",map("tenant",a.tenant().id(),"member",i.memberId(),"period",i.periodStart()));UUID id=existing.isEmpty()?UUID.randomUUID():(UUID)existing.getFirst().get("id");if(!existing.isEmpty()){version(existing.getFirst(),i.expectedVersion());if("LOCKED".equals(existing.getFirst().get("status")))throw ApiError.conflict("已锁定提成不能重算，请登记调整");}var p=map("id",id,"tenant",a.tenant().id(),"member",i.memberId(),"period",i.periodStart(),"rule",i.ruleId(),"rversion",rule.get("version"),"base",base,"amount",commission,"snapshot",t.body(tiers),"hash",hash,"creator",a.tenant().memberId());if(existing.isEmpty())t.db.update("INSERT INTO crm_commission_run(id,tenant_id,member_id,period_start,rule_id,rule_version,base_cents,commission_cents,rule_snapshot,source_hash,created_by_member_id) VALUES(:id,:tenant,:member,:period,:rule,:rversion,:base,:amount,cast(:snapshot AS jsonb),:hash,:creator)",p);else t.db.update("UPDATE crm_commission_run SET rule_id=:rule,rule_version=:rversion,base_cents=:base,commission_cents=:amount,rule_snapshot=cast(:snapshot AS jsonb),source_hash=:hash,status='DRAFT',reviewed_by_member_id=NULL,created_by_member_id=:creator,version=version+1,updated_at=now() WHERE tenant_id=:tenant AND id=:id",p);var current=run(a,id);event(a,"COMMISSION",id,number(current,"version"),"CALCULATED","",current,trace);return id;});return run(a,result);});}
 public Object runAction(AuthService.Session s,UUID id,String action,Decision i,String key,UUID trace){return t.scoped(s,"contract",true,a->{managerial(a);UUID result=t.once(a,"commission."+action,key,new TradeService.Target(id,i),()->{var r=run(a,id);member(a,(UUID)r.get("memberId"),true);version(r,i.expectedVersion());String state=(String)r.get("status");separate(a,(UUID)r.get("memberId"));if(action.equals("adjust")){if(!state.equals("LOCKED")||i.deltaCents()==null||i.deltaCents()==0||text(i.reason()).isEmpty())throw ApiError.bad("仅已锁定提成可填写金额与原因追加调整");t.db.update("INSERT INTO crm_commission_adjustment(id,tenant_id,run_id,delta_cents,reason,actor_member_id) VALUES(:adjust,:tenant,:id,:delta,:reason,:member)",map("adjust",UUID.randomUUID(),"tenant",a.tenant().id(),"id",id,"delta",i.deltaCents(),"reason",text(i.reason()),"member",a.tenant().memberId()));}else{String currentHash=Crypto.hash(t.body(sources(a,(UUID)r.get("memberId"),null,(LocalDate)r.get("periodStart"),((LocalDate)r.get("periodStart")).plusMonths(1))));if(!currentHash.equals(r.get("sourceHash")))throw ApiError.conflict("回款或可见范围已变化，请重算后再复核");if(action.equals("review")){if(!state.equals("DRAFT"))throw ApiError.conflict("仅草稿可复核");separate(a,(UUID)r.get("createdByMemberId"));}else if(action.equals("lock")){if(!state.equals("REVIEWED"))throw ApiError.conflict("先由另一位主管复核，再锁定");if(!((LocalDate)r.get("periodStart")).plusMonths(1).isBefore(today())&&!((LocalDate)r.get("periodStart")).plusMonths(1).equals(today()))throw ApiError.conflict("月份结束后才能锁定");}else throw ApiError.bad("提成操作无效");}
 t.db.update("UPDATE crm_commission_run SET status=:state,reviewed_by_member_id=CASE WHEN :action='review' THEN :member ELSE reviewed_by_member_id END,locked_at=CASE WHEN :action='lock' THEN now() ELSE locked_at END,version=version+1,updated_at=now() WHERE tenant_id=:tenant AND id=:id",map("tenant",a.tenant().id(),"id",id,"action",action,"state",action.equals("review")?"REVIEWED":action.equals("lock")?"LOCKED":state,"member",a.tenant().memberId()));var updated=run(a,id);event(a,"COMMISSION",id,number(updated,"version"),action.toUpperCase(Locale.ROOT),text(i.reason()),updated,trace);return id;});return run(a,result);});}
 private Map<String,Object> weekly(AuthService.Actor a,UUID id){var r=t.one("SELECT w.*,m.display_name AS member_name FROM crm_sales_weekly_report w JOIN sys_tenant_member m ON m.tenant_id=w.tenant_id AND m.id=w.member_id WHERE w.tenant_id=:tenant AND w.id=:id",map("tenant",a.tenant().id(),"id",id));member(a,(UUID)r.get("memberId"),false);return r;}
 public Object weeklies(AuthService.Session s,LocalDate start){date(start);return t.scoped(s,"contract",false,a->{var ids=t.db.queryForList("SELECT id FROM crm_sales_weekly_report WHERE tenant_id=:tenant AND week_start=:week ORDER BY updated_at DESC",map("tenant",a.tenant().id(),"week",start),UUID.class);var result=new ArrayList<Map<String,Object>>();for(UUID id:ids)try{result.add(weekly(a,id));}catch(ApiError ignored){}return map("items",result);});}
 public Object weeklySave(AuthService.Session s,UUID id,WeeklyInput i,String key,UUID trace){date(i.weekStart());if(i.weekStart().getDayOfWeek()!=DayOfWeek.MONDAY||i.weekStart().isAfter(today()))throw ApiError.bad("周起始日需为不晚于今天的周一");return t.scoped(s,"contract",true,a->{UUID selected=id==null?t.once(a,"weekly.create",key,i,()->{UUID n=UUID.randomUUID();var p=weeklyParams(a,n,i);t.db.update("INSERT INTO crm_sales_weekly_report(id,tenant_id,member_id,week_start,progress,achievements,risks,next_actions,confirmed_cents) VALUES(:id,:tenant,:member,:week,:progress,:achievements,:risks,:next,:cash)",p);event(a,"WEEKLY",n,0,"CREATED","",i,trace);return n;}):id;if(id!=null){var old=weekly(a,id);if(!a.tenant().memberId().equals(old.get("memberId"))||!"DRAFT".equals(old.get("status"))||!old.get("weekStart").equals(i.weekStart()))throw ApiError.forbidden("仅本人可修改同一周的草稿");version(old,i.expectedVersion());t.db.update("UPDATE crm_sales_weekly_report SET progress=:progress,achievements=:achievements,risks=:risks,next_actions=:next,confirmed_cents=:cash,version=version+1,updated_at=now() WHERE tenant_id=:tenant AND id=:id",weeklyParams(a,id,i));event(a,"WEEKLY",id,i.expectedVersion()+1,"UPDATED","",i,trace);}return weekly(a,selected);});}
 private Map<String,Object> weeklyParams(AuthService.Actor a,UUID id,WeeklyInput i){return map("id",id,"tenant",a.tenant().id(),"member",a.tenant().memberId(),"week",i.weekStart(),"progress",text(i.progress()),"achievements",text(i.achievements()),"risks",text(i.risks()),"next",text(i.nextActions()),"cash",actual(a,a.tenant().memberId(),null,i.weekStart(),i.weekStart().plusDays(7)));}
 public Object weeklyAction(AuthService.Session s,UUID id,String action,Decision i,String key,UUID trace){return t.scoped(s,"contract",true,a->{UUID result=t.once(a,"weekly."+action,key,new TradeService.Target(id,i),()->{var r=weekly(a,id);version(r,i.expectedVersion());String state=(String)r.get("status"),next;long cash=number(r,"confirmedCents");if(action.equals("submit")){if(!a.tenant().memberId().equals(r.get("memberId"))||!state.equals("DRAFT"))throw ApiError.forbidden("仅本人可提交周报草稿");next="SUBMITTED";cash=actual(a,(UUID)r.get("memberId"),null,(LocalDate)r.get("weekStart"),((LocalDate)r.get("weekStart")).plusDays(7));}else{managerial(a);member(a,(UUID)r.get("memberId"),true);separate(a,(UUID)r.get("memberId"));if(!state.equals("SUBMITTED"))throw ApiError.conflict("仅待审核周报可审批");if(!Set.of("approve","reject").contains(action))throw ApiError.bad("周报操作无效");if(action.equals("reject")&&text(i.reason()).isEmpty())throw ApiError.bad("请填写退回原因");next=action.equals("approve")?"APPROVED":"DRAFT";}t.db.update("UPDATE crm_sales_weekly_report SET status=:state,confirmed_cents=:cash,reviewed_by_member_id=CASE WHEN :state='SUBMITTED' THEN NULL ELSE :member END,review_reason=:reason,version=version+1,updated_at=now() WHERE tenant_id=:tenant AND id=:id",map("tenant",a.tenant().id(),"id",id,"state",next,"cash",cash,"member",a.tenant().memberId(),"reason",text(i.reason())));var current=weekly(a,id);event(a,"WEEKLY",id,number(current,"version"),action.toUpperCase(Locale.ROOT),text(i.reason()),current,trace);return id;});return weekly(a,result);});}
 private void event(AuthService.Actor a,String type,UUID id,long version,String action,String reason,Object snapshot,UUID trace){t.db.update("INSERT INTO crm_performance_event(id,tenant_id,entity_type,entity_id,business_version,action,reason,snapshot,actor_member_id) VALUES(:event,:tenant,:type,:id,:version,:action,:reason,cast(:snapshot AS jsonb),:member)",map("event",UUID.randomUUID(),"tenant",a.tenant().id(),"type",type,"id",id,"version",version,"action",action,"reason",reason,"snapshot",t.body(snapshot),"member",a.tenant().memberId()));t.audit(a,type+"_"+action,type,id,version,trace);}
 public Object history(AuthService.Session s,String type,UUID id){return t.scoped(s,"contract",false,a->{switch(type){case "TARGET"->targetScope(a,t.one("SELECT * FROM crm_sales_target WHERE tenant_id=:tenant AND id=:id",map("tenant",a.tenant().id(),"id",id)),false);case "COMMISSION"->run(a,id);case "WEEKLY"->weekly(a,id);case "RULE"->t.one("SELECT id FROM crm_commission_rule WHERE tenant_id=:tenant AND id=:id",map("tenant",a.tenant().id(),"id",id));default->throw ApiError.bad("对象类型无效");}return map("items",t.rows("SELECT e.business_version,e.action,e.reason,e.created_at,m.display_name AS actor_name FROM crm_performance_event e JOIN sys_tenant_member m ON m.tenant_id=e.tenant_id AND m.id=e.actor_member_id WHERE e.tenant_id=:tenant AND e.entity_type=:type AND e.entity_id=:id ORDER BY business_version DESC",map("tenant",a.tenant().id(),"type",type,"id",id)));});}
}
